import os
import shutil


def task_func(src_folder, backup_dir):
    if not os.path.isdir(src_folder):
        raise ValueError("Source folder does not exist.")

    abs_src = os.path.abspath(src_folder)
    abs_backup_root = os.path.abspath(backup_dir)
    backup_name = os.path.basename(os.path.normpath(abs_src))
    backup_path = os.path.join(abs_backup_root, backup_name)

    # Prevent copying a folder into itself or its subfolder.
    try:
        if os.path.commonpath([abs_src, os.path.abspath(backup_path)]) == abs_src:
            return False
    except Exception:
        return False

    try:
        os.makedirs(abs_backup_root, exist_ok=True)

        if os.path.exists(backup_path):
            if os.path.isdir(backup_path):
                shutil.rmtree(backup_path)
            else:
                os.remove(backup_path)

        shutil.copytree(abs_src, backup_path)
    except Exception:
        return False

    try:
        shutil.rmtree(abs_src)
    except Exception as exc:
        raise Exception("Error deleting source folder.") from exc

    return True
